import {FieldValidatorFn} from "../types/field-validator-fn";

// this validator was entirely generated by claude
export const dateValidator: FieldValidatorFn = (value: string) => {
    // checks for four numbers, then two numbers, and again two numbers and is divided by a '-'
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
        return 'Muss das Format YYYY-MM-DD haben.';
    }

    // first value has to be year, then month, then day.
    const [year, month, day] = value.split('-').map(Number);
    const date = new Date(Date.UTC(year, month - 1, day));

    // checks if new Date object has the same year, month and day as the given value.
    const isReal =
        date.getUTCFullYear() === year &&
        date.getUTCMonth() === month - 1 &&
        date.getUTCDate() === day;

    return isReal ? null : 'Ist kein gültiges Datum.';
};
